SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @i int=1;WHILE @i<=4000 BEGIN BEGIN TRAN;INSERT lab.CommitRows VALUES(@i,REPLICATE('S',200));COMMIT;SET @i+=1;END;INSERT lab.Evidence SELECT 'SINGLE_COMMIT',SUM(v.num_of_writes),SUM(v.num_of_bytes_written),COALESCE((SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type='WRITELOG'),0),(SELECT COUNT_BIG(*) FROM lab.CommitRows),(SELECT CHECKSUM_AGG(BINARY_CHECKSUM(RowId,Payload)) FROM lab.CommitRows) FROM sys.dm_io_virtual_file_stats(DB_ID(),NULL)v JOIN sys.database_files f ON f.file_id=v.file_id WHERE f.type=1;PRINT 'SQLPERF_SUMMARY|PASS|OK';
